shortcuts.codeOnPrepare:
var WEB = 'https://personal.bomberostenerife.com';
var APP = 'https://script.google.com/macros/s/AKfycbxt4jty_VyTMWPDEZqn6YeqZDQ8mqUHIQAdEOfPxo6e1Z-ltxuT__KxGV8llBiEkzdg/exec';
function v(k) { try { return String(getVariable(k) || ''); } catch (e) { return ''; } }
function parar(m) { showDialog(m, 'Panel BT'); throw new Error(m); }

// --- número y contraseña de Gestión de Personal: se piden la primera vez y se quedan en esta app
var usuario = v('pbt_usuario'), clave = v('pbt_clave');
if (!usuario || !clave) {
  usuario = prompt('Panel BT: tu número corporativo (el usuario de Gestión de Personal). Solo se pide la primera vez.', usuario) || '';
  if (!usuario) parar('Sin número no puedo entrar en Gestión de Personal.');
  clave = promptPassword('Panel BT: tu contraseña de Gestión de Personal. Se guarda solo en este móvil.') || '';
  if (!clave) parar('Sin contraseña no puedo entrar en Gestión de Personal.');
  setVariable('pbt_usuario', usuario.trim());
  setVariable('pbt_clave', clave);
}
var codigo = v('pbt_codigo'), consultas = [];
try { consultas = JSON.parse(v('pbt_consultas') || '[]'); } catch (e) {}
if (!codigo || !consultas.length) parar('Esto se abre desde Panel BT: botón «🌐 De Gestión de Personal».');

// --- cookies a mano (sendHttpRequest no las guarda)
var jar = {};
function cogerCookies(r) {
  if (!r || !r.response) return;
  var h = r.response.headers || {};
  for (var k in h) {
    if (String(k).toLowerCase() !== 'set-cookie') continue;
    var lista = Array.isArray(h[k]) ? h[k] : [h[k]];
    for (var i = 0; i < lista.length; i++) {
      var par = String(lista[i]).split(';')[0], j = par.indexOf('=');
      if (j > 0) jar[par.slice(0, j).trim()] = par.slice(j + 1).trim();
    }
  }
}
function cookies() { var s = []; for (var k in jar) s.push(k + '=' + jar[k]); return s.join('; '); }
function pedir(url, form, seguir) {
  var op = { method: form ? 'POST' : 'GET', headers: { 'Cookie': cookies() }, charset: 'ISO-8859-1', followRedirects: !!seguir };
  if (form) op.formData = form;
  var r = sendHttpRequest(url, op);
  if (r.status === 'networkError')
    parar('No llego a Gestión de Personal. Pon la VPN (o el wifi del trabajo) y vuelve a pulsar el botón en Panel BT.');
  cogerCookies(r);
  var cuerpo = (r.response && r.response.body) || '';
  // si redirige, se sigue a mano para no perder las cookies
  var cod = r.response ? r.response.statusCode : 0, h = (r.response && r.response.headers) || {}, loc = '';
  for (var k in h) if (String(k).toLowerCase() === 'location') loc = String(Array.isArray(h[k]) ? h[k][0] : h[k]);
  if (cod >= 300 && cod < 400 && loc) {
    if (!/^https?:/.test(loc)) loc = loc.charAt(0) === '/' ? WEB + loc : url.replace(/[?#].*$/, '').replace(/[^\/]*$/, '') + loc;
    return pedir(loc, null, false);
  }
  return cuerpo;
}
// la página viene leída letra a letra (ISO-8859-1); si en realidad es UTF-8, se arregla
function texto(s) {
  var m = /charset=["']?([\w-]+)/i.exec(s.slice(0, 3000));
  if (!m || /^utf/i.test(m[1])) { try { return decodeURIComponent(escape(s)); } catch (e) {} }
  return s;
}

// 1. entrar
pedir(WEB + '/');
pedir(WEB + '/index2.php', { user: usuario, pass: clave, hd_sended: '1' });
// 2. «Gestión de Asistencia Diaria» y su «sesion»
var form = pedir(WEB + '/usuarios/gDiario-guardia.php');
if (form.indexOf('sel_parque') < 0) {
  if (confirm('Gestión de Personal no me ha dejado entrar. ¿Borro el número y la contraseña guardados para escribirlos otra vez la próxima vez?')) {
    setVariable('pbt_usuario', ''); setVariable('pbt_clave', '');
  }
  parar('No he podido entrar en Gestión de Personal. Mira el número y la contraseña, y que tengas la VPN o el wifi del trabajo.');
}
var ms = /name="sesion"[^>]*value="(\d*)"|value="(\d*)"[^>]*name="sesion"/i.exec(form);
var sesion = ms ? (ms[1] || ms[2] || '') : '';
// 3. una tabla por parque y día
var tablas = [];
for (var i = 0; i < consultas.length; i++) {
  var q = consultas[i];
  var html = texto(pedir(WEB + '/usuarios/functions/tabla-diario.php?aleatorio=4815162342',
                         { fecha: q.fecha, fecha_f: q.fecha, sel_parque: q.sel, sesion: sesion }));
  tablas.push({ parque: q.parque, fecha: q.fecha, opcion: q.opcion, html: html });
}
// 4. quitar la VPN y mandarlo a Panel BT
showDialog('Ya tengo la guardia de Gestión de Personal. Si estás con la VPN, desconéctala ahora (para que llegue a Panel BT) y pulsa OK. En el wifi del trabajo, pulsa OK sin más.', 'Panel BT');
var fallos = [];
for (var i = 0; i < tablas.length; i++) {
  var t = tablas[i], ok = false;
  for (var intento = 0; intento < 2 && !ok; intento++) {
    var r = sendHttpRequest(APP, { method: 'POST', headers: { 'Content-Type': 'application/json' }, followRedirects: true,
      body: JSON.stringify({ accion: 'subir_diario', codigo: codigo, parque: t.parque, fecha: t.fecha, opcion: t.opcion, html: t.html }) });
    ok = r.status === 'success' && /"ok"\s*:\s*true/.test((r.response && r.response.body) || '');
  }
  if (!ok) fallos.push(t.parque + ' ' + t.fecha);
}
if (fallos.length) showDialog('No he podido mandar a Panel BT: ' + fallos.join(', ') + '. ¿Sigue puesta la VPN? Quítala y vuelve a pulsar el botón en Panel BT.', 'Panel BT');
else showDialog('Listo: vuelve a Panel BT.', 'Panel BT');
